def stats(values):
    return {'median': st.median(values), 'min': min(values), 'max': max(values),
            'byRound': values}

def signature(sample):
    c = sample['counters']
    return (tuple(c[k] for k in ('compiledBinds','interpretedBinds','aggregateCompiledBinds','aggregateInterpretedBinds')),
            tuple(sorted(tuple(x[k] for k in ('point','label','strategy','mode','count'))
                         for x in sample['successfulSelections'])))

